export function UndoHistory({
  currentStep = {{currentStep}},
  accent = "{{accent}}",
  layout = "{{layout}}",
  canRedo = {{canRedo}},
  showTimestamps = {{showTimestamps}},
}) {
  const timeline = layout === "timeline";
  const items = [
    { text: "Typed opening paragraph", state: "done", time: "2m ago" },
    { text: "Bolded heading", state: "done", time: "90s ago" },
    { text: "Inserted image", state: "current", time: null },
    { text: "Deleted stray sentence", state: "pending", time: null },
    { text: "Reordered sections", state: "pending", time: null },
  ];
  return (
    <div style={{ fontFamily: "system-ui, sans-serif", color: "#241430", background: "#FAF7F2", padding: 18, maxWidth: 320 }}>
      <div style={{ height: 4, background: "#24143014", borderRadius: 2, overflow: "hidden", marginBottom: 14 }}>
        <span style={{ display: "block", height: "100%", width: `calc(20% * ${currentStep})`, background: accent }} />
      </div>
      <ol style={{ listStyle: "none", margin: "0 0 14px", padding: 0, display: "flex", flexDirection: "column", gap: 8 }}>
        {items.map((it) => (
          <li key={it.text} style={{
            fontSize: 13,
            fontWeight: it.state === "current" ? 700 : 400,
            color: it.state === "pending" ? "#241430aa" : "#241430",
            textDecoration: it.state === "pending" ? "line-through" : "none",
            borderLeft: timeline ? `2px solid ${it.state === "current" ? accent : "#24143020"}` : "none",
            borderBottom: timeline ? "none" : "1px solid #24143014",
            paddingLeft: timeline ? 12 : 0,
            paddingBottom: timeline ? 0 : 8,
          }}>
            {it.text}
            {showTimestamps && it.time && <span style={{ marginLeft: 6, fontSize: 11, color: "#241430aa" }}>{it.time}</span>}
            {it.state === "current" && <span style={{ marginLeft: 6, fontSize: 10, fontWeight: 700, textTransform: "uppercase", color: accent }}>You are here</span>}
          </li>
        ))}
      </ol>
      <div style={{ display: "flex", gap: 8 }}>
        <button type="button" style={{ border: "1.5px solid #24143026", background: "#fff", padding: "6px 14px", borderRadius: 8, fontSize: 13, fontWeight: 600, cursor: "pointer" }}>Undo</button>
        <button type="button" disabled={!canRedo} aria-disabled={!canRedo} style={{ border: "1.5px solid #24143026", background: "#fff", padding: "6px 14px", borderRadius: 8, fontSize: 13, fontWeight: 600,
          cursor: canRedo ? "pointer" : "not-allowed", opacity: canRedo ? 1 : 0.45 }}>Redo</button>
      </div>
    </div>
  );
}
